import math
def solve(query, vectors, k):
    def cos(a,b):
      na=math.sqrt(sum(x*x for x in a)); nb=math.sqrt(sum(x*x for x in b))
      return sum(x*y for x,y in zip(a,b))/(na*nb) if na and nb else 0.0
    return sorted(range(len(vectors)),key=lambda i:(-cos(query,vectors[i]),i))[:k]

def solve(exact_neighbors, approximate_neighbors, k):
    vals=[]
    for e,a in zip(exact_neighbors,approximate_neighbors):
      denom=len(set(e[:k])); vals.append(len(set(e[:k])&set(a[:k]))/denom if denom else 0.0)
    return sum(vals)/len(vals) if vals else 0.0

